### Enhanced Version with Additional Context

```php
<?php

/**
 * Returns a human-readable label for a given order status string.
 * Optionally includes an emoji icon and/or a description.
 *
 * @param string $status      The order status identifier.
 * @param bool   $withIcon    Whether to include an emoji icon.
 * @param bool   $withDetails Whether to include a short description.
 * @return string A human-readable label for the status.
 */
function getOrderStatusLabel(
    string $status,
    bool $withIcon = false,
    bool $withDetails = false
): string {
    $statusMap = [
        'pending' => [
            'label'       => 'Pending',
            'icon'        => '🕐',
            'description' => 'Your order has been received and is awaiting processing.',
        ],
        'shipped' => [
            'label'       => 'Shipped',
            'icon'        => '📦',
            'description' => 'Your order is on its way.',
        ],
        'delivered' => [
            'label'       => 'Delivered',
            'icon'        => '✅',
            'description' => 'Your order has been successfully delivered.',
        ],
        'cancelled' => [
            'label'       => 'Cancelled',
            'icon'        => '❌',
            'description' => 'Your order has been cancelled.',
        ],
    ];

    // Normalize input to handle inconsistent casing
    $normalizedStatus = strtolower(trim($status));

    if (!array_key_exists($normalizedStatus, $statusMap)) {
        return 'Unknown Status';
    }

    $entry  = $statusMap[$normalizedStatus];
    $output = $entry['label'];

    if ($withIcon) {
        $output = $entry['icon'] . ' ' . $output;
    }

    if ($withDetails) {
        $output .= ' — ' . $entry['description'];
    }

    return $output;
}
```

