## `isAdmin()` PHP Function

### Basic Implementation

```php
<?php

/**
 * Check if a user has the admin role.
 *
 * @param object|array $user The user object or array to check.
 * @return bool True if the user is an admin, false otherwise.
 */
function isAdmin($user): bool
{
    if ($user === null) {
        return false;
    }

    // Handle object with roles array (e.g., ['admin', 'editor'])
    if (is_object($user) && isset($user->roles) && is_array($user->roles)) {
        return in_array('admin', $user->roles, strict: true);
    }

    // Handle object with single role property (e.g., 'admin')
    if (is_object($user) && isset($user->role)) {
        return $user->role === 'admin';
    }

    // Handle associative array with roles array
    if (is_array($user) && isset($user['roles']) && is_array($user['roles'])) {
        return in_array('admin', $user['roles'], strict: true);
    }

    // Handle associative array with single role key
    if (is_array($user) && isset($user['role'])) {
        return $user['role'] === 'admin';
    }

    return false;
}
```

