/**
 * Check if a user has the admin role.
 * Supports single role (string) and multiple roles (array).
 *
 * @param object|array $user The user object or array containing role information
 * @return bool True if the user is an admin, false otherwise
 */
function isAdmin($user): bool
{
    if (empty($user)) {
        return false;
    }

    // Extract the role value from object or array
    $role = match (true) {
        is_object($user) && isset($user->role) => $user->role,
        is_array($user) && isset($user['role']) => $user['role'],
        default                                 => null,
    };

    if ($role === null) {
        return false;
    }

    // Support both single role string and array of roles
    if (is_array($role)) {
        return in_array('admin', $role, strict: true);
    }

    return $role === 'admin';
}
```

