        }

        // Check for a getRoles() method returning an array
        if (method_exists($user, 'getRoles')) {
            return in_array('admin', $user->getRoles(), true);
        }

        // Check for a direct property
        if (property_exists($user, 'role')) {
            return $user->role === 'admin';
        }

        // Check for roles array property
        if (property_exists($user, 'roles')) {
            return in_array('admin', (array) $user->roles, true);
        }
    }

    return false;
}
